/* ===== Preloader: 3 ثوانٍ عند أول زيارة للجلسة، ثم 1.2 ثانية بين الصفحات ===== */
(function(){
  var started=Date.now(),done=false,loaded=document.readyState==='complete',duration=1200;
  try{
    if(!sessionStorage.getItem('norda_preloader_seen')){
      duration=3000;
      sessionStorage.setItem('norda_preloader_seen','1');
    }
  }catch(e){duration=3000}
  function finishWhenReady(){
    if(done||!loaded)return;
    var wait=Math.max(0,duration-(Date.now()-started));
    setTimeout(function(){
      if(done)return;done=true;
      var p=document.getElementById('preloader');
      if(!p)return;
      p.classList.add('done');
      setTimeout(function(){p.remove()},700);
    },wait);
  }
  if(!loaded)window.addEventListener('load',function(){loaded=true;finishWhenReady()},{once:true});
  finishWhenReady();
})();

/* ===== انتقالات الصفحات: fade-out ثم الانتقال ===== */
(function(){
  /* وجود Preloader يكفي، فلا نفعّل الانتقال لتفادي الوميض المزدوج */
  if(document.getElementById('preloader'))return;
  if(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  document.addEventListener('click',function(e){
    if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;
    var a=e.target.closest&&e.target.closest('a[href]');
    if(!a||a.target==='_blank'||a.hasAttribute('download'))return;
    var h=a.getAttribute('href')||'';
    if(!h||h.charAt(0)==='#'||/^(mailto:|tel:|javascript:)/i.test(h))return;
    if(a.origin!==location.origin)return;                       /* روابط خارجية */
    if(a.pathname===location.pathname&&a.search===location.search&&a.hash)return; /* مرساة داخل نفس الصفحة */
    e.preventDefault();
    document.body.classList.add('page-out');
    setTimeout(function(){location.href=a.href},280);
  });
  /* عند الرجوع من bfcache تُزال حالة الإخفاء */
  window.addEventListener('pageshow',function(e){if(e.persisted)document.body.classList.remove('page-out')});
})();

/* ===== الشريط العلوي: يتغير شكله عند التمرير ===== */
(function(){
  var h=document.querySelector('header');if(!h)return;
  function upd(){h.classList.toggle('scrolled',(window.pageYOffset||document.documentElement.scrollTop||0)>20)}
  window.addEventListener('scroll',upd,{passive:true});upd();
})();

/* ===== شريط تقدم القراءة ===== */
(function(){
  var w=document.createElement('div'),b=document.createElement('div'),tick=false;
  w.id='readProgress';w.setAttribute('aria-hidden','true');b.className='bar';w.appendChild(b);
  document.body.insertBefore(w,document.body.firstChild);
  function paint(){
    tick=false;
    var e=document.documentElement,max=e.scrollHeight-e.clientHeight,y=window.pageYOffset||e.scrollTop||0;
    b.style.width=(max>0?Math.min(100,Math.max(0,y/max*100)):0)+'%';
  }
  function req(){if(!tick){tick=true;requestAnimationFrame(paint)}}
  window.addEventListener('scroll',req,{passive:true});
  window.addEventListener('resize',req,{passive:true});
  paint();
})();

/* ===== زر العودة للأعلى ===== */
(function(){
  var b=document.createElement('button'),rm=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)');
  b.type='button';b.id='toTop';b.setAttribute('aria-label','العودة للأعلى');
  b.innerHTML='<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 19V5M5 12l7-7 7 7"/></svg>';
  document.body.appendChild(b);
  function upd(){b.classList.toggle('show',(window.pageYOffset||document.documentElement.scrollTop||0)>400)}
  window.addEventListener('scroll',upd,{passive:true});upd();
  b.addEventListener('click',function(){window.scrollTo({top:0,behavior:(rm&&rm.matches)?'auto':'smooth'})});
})();

